property.code:
require(['jquery', 'xwiki-meta'], function($, xm) {
  // Start the review of an imported document from the table of the SOP Manager.
  var serviceURL = new XWiki.Document('ContentMenuAddToReviewUIX', 'SOPManager.Code').getURL('get',
    'outputSyntax=plain');
  $(document).on('click', '#sopManagerTable .sopStartReview', function(event) {
    event.preventDefault();
    var button = $(this).prop('disabled', true);
    $.post(serviceURL, {
      'document': button.attr('data-document'),
      'form_token': xm.form_token
    }).done(function() {
      window.location = new XWiki.Document(XWiki.Model.resolve(button.attr('data-document'),
        XWiki.EntityType.DOCUMENT)).getURL('view', 'r=1') + '#SOPReviewPages';
    }).fail(function() {
      button.prop('disabled', false);
      new XWiki.widgets.Notification($jsontool.serialize($services.localization.render('sopManager.liveTable.startReview.error')), 'error');
    });
  });
});
